// Generates lightweight PNG fallback icons for PWA and mobile packaging
import fs from 'fs';
import path from 'path';

// Valid 192x192 blue icon PNG data URI
const pngBase64 = "";
const buffer = Buffer.from(pngBase64, 'base64');

const publicDir = path.resolve('public');
if (!fs.existsSync(publicDir)) {
  fs.mkdirSync(publicDir, { recursive: true });
}

fs.writeFileSync(path.join(publicDir, 'pwa-192x192.png'), buffer);
fs.writeFileSync(path.join(publicDir, 'pwa-512x512.png'), buffer);
fs.writeFileSync(path.join(publicDir, 'apple-touch-icon.png'), buffer);
console.log('Icons written successfully to /public');
